import Foundation

enum FreeExerciseDBIndex {
    private struct ExerciseItem: Decodable {
        let id: String?
        let name: String?
        let steps: [String: [String]]?
    }

    private static let lock = NSLock()
    nonisolated(unsafe) private static var isLoaded = false
    nonisolated(unsafe) private static var instructionsIndex: [String: [String: String]] = [:]

    static func lookupImageURL(name: String, aliases: [String] = []) -> String? {
        let candidates = [name] + aliases
        for candidate in candidates {
            let key = normalize(candidate)
            if let url = imageIndex[key] {
                return url
            }
        }
        return nil
    }

    static func lookupInstructions(name: String, aliases: [String] = [], language: String) -> String? {
        ensureLoaded()
        let langKey = langCode(from: language)
        let candidates = [name] + aliases

        for candidate in candidates {
            let key = normalize(candidate)
            if let langDict = instructionsIndex[key], let inst = langDict[langKey] ?? langDict["es"] ?? langDict["en"] {
                return inst
            }
        }
        return nil
    }

    private static func ensureLoaded() {
        lock.lock()
        defer { lock.unlock() }
        guard !isLoaded else { return }

        guard let url = Bundle.main.url(forResource: "exercises", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let items = try? JSONDecoder().decode([ExerciseItem].self, from: data) else {
            isLoaded = true
            return
        }

        var tempInstructions: [String: [String: String]] = [:]

        for item in items {
            guard let steps = item.steps, !steps.isEmpty else { continue }
            var langFormatted: [String: String] = [:]
            for (lang, stepList) in steps {
                if !stepList.isEmpty {
                    langFormatted[lang] = stepList.enumerated().map { "\($0.offset + 1). \($0.element)" }.joined(separator: "\n")
                }
            }

            let keys = [item.name, item.id].compactMap { $0 }.map(normalize).filter { !$0.isEmpty }
            for key in keys {
                tempInstructions[key] = langFormatted
            }
        }

        let aliasToTargetMap: [String: String] = [
            "barbellpullover": "bentarmbarbellpullover",
            "pullover": "bentarmbarbellpullover",
            "barbellbenchpress": "barbellbenchpressmediumgrip",
            "benchpress": "barbellbenchpressmediumgrip",
            "overheadpress": "standingmilitarypress",
            "barbellsquat": "barbellfullsquat",
            "squat": "barbellfullsquat",
            "pushup": "pushups",
            "walkinglunge": "dumbbelllunges",
            "pullup": "pullups",
            "bandrow": "backflyeswithbands",
            "bandfacepull": "facepull",
            "lateralraise": "sidelateralraise",
            "dumbbellcurl": "inclinedumbbellcurl",
            "overheadtricepsextension": "cableropeoverheadtricepsextension",
            "bulgariansplitsquat": "smithsinglelegsplitsquat",
            "splitsquat": "smithsinglelegsplitsquat",
            "standingcalfraise": "rockingstandingcalfraise",
            "calfraise": "rockingstandingcalfraise",
            "mountainclimber": "mountainclimbers",
            "kettlebellswing": "onearmkettlebellswings",
            "stationarybike": "airbike",
            "treadmillrun": "runningtreadmill",
            "rowingmachine": "rowingstationary"
        ]

        for (alias, target) in aliasToTargetMap {
            if let targetDict = tempInstructions[target] {
                tempInstructions[alias] = targetDict
            }
        }

        instructionsIndex = tempInstructions
        isLoaded = true
    }

    private static func langCode(from language: String) -> String {
        let lower = language.lowercased()
        if lower.hasPrefix("es") { return "es" }
        if lower.hasPrefix("it") { return "it" }
        if lower.hasPrefix("fr") { return "fr" }
        if lower.hasPrefix("de") { return "de" }
        if lower.hasPrefix("ru") { return "ru" }
        if lower.hasPrefix("zh") { return "zh" }
        if lower.hasPrefix("hi") { return "hi" }
        if lower.hasPrefix("pl") { return "pl" }
        if lower.hasPrefix("ko") { return "ko" }
        if lower.hasPrefix("tr") { return "tr" }
        return "en"
    }

    private static func normalize(_ string: String) -> String {
        string.lowercased().components(separatedBy: CharacterSet.alphanumerics.inverted).joined()
    }

